export class ForwardSurface {
  constructor(private readonly _client: BridgethingClient) {}

  /** Subscribe to `Forward::Text` from the daemon. */
  onText(handler: (msg: string) => void): () => void {
    return this._client.on(event => {
      if (event.type !== 'message') return;
      const data = event.message.data;
      if (data.type !== 'forward') return;
      const inner = data.data;
      if (inner.encoding !== 'text') return;
      handler(inner.data);
    });
  }

  /** Subscribe to `Forward::Json` from the daemon. */
  onJson(handler: (msg: unknown) => void): () => void {
    return this._client.on(event => {
      if (event.type !== 'message') return;
      const data = event.message.data;
      if (data.type !== 'forward') return;
      const inner = data.data;
      if (inner.encoding !== 'json') return;
      handler(inner.data);
    });
  }

  /** Subscribe to `Forward::Binary` from the daemon. */
  onBinary(handler: (msg: Uint8Array) => void): () => void {
    return this._client.on(event => {
      if (event.type !== 'message') return;
      const data = event.message.data;
      if (data.type !== 'forward') return;
      const inner = data.data;
      if (inner.encoding !== 'binary') return;
      handler(inner.data);
    });
  }

  /** Exhaustive subscribe over all inbound `Forward` variants. */
  subscribe(handlers: ForwardInboundHandlers): () => void {
    return this._subscribe(handlers, false);
  }

  /** Same as `subscribe` but every handler is optional. */
  subscribePartial(handlers: Partial<ForwardInboundHandlers>): () => void {
    return this._subscribe(handlers, true);
  }

  private _subscribe(handlers: Partial<ForwardInboundHandlers>, partial: boolean): () => void {
    return this._client.on(event => {
      if (event.type !== 'message') return;
      const data = event.message.data;
      if (data.type !== 'forward') return;
      const inner = data.data;
      switch (inner.encoding) {
        case 'text': {
          handlers.text?.(inner.data);
          return;
        }
        case 'json': {
          handlers.json?.(inner.data);
          return;
        }
        case 'binary': {
          handlers.binary?.(inner.data);
          return;
        }
        default: {
          if (!partial) this._client.logger.warn('Forward: no handler for inner', inner);
          return;
        }
      }
    });
  }

  /** Send `Forward::Text` to the daemon. */
  async text(payload: string): Promise<void> {
    const msg: ClientToBridgeMsg = {
      id: newUuid(),
      meta: { kind: 'event' },
      data: { type: 'forward', data: { encoding: 'text', data: payload } },
    };
    await this._client.send(msg);
  }

  /** Send `Forward::Json` to the daemon. */
  async json(payload: unknown): Promise<void> {
    const msg: ClientToBridgeMsg = {
      id: newUuid(),
      meta: { kind: 'event' },
      data: { type: 'forward', data: { encoding: 'json', data: payload } },
    };
    await this._client.send(msg);
  }

  /** Send `Forward::Binary` to the daemon. */
  async binary(payload: Uint8Array): Promise<void> {
    const msg: ClientToBridgeMsg = {
      id: newUuid(),
      meta: { kind: 'event' },
      data: { type: 'forward', data: { encoding: 'binary', data: payload } },
    };
    await this._client.send(msg);
  }
}

